import React from "react";
import {
  BrowserRouter,
  Routes,
  Route,
  NavLink,
} from "react-router-dom";

import "../styles/Home.css";

/* =========================
   SIDEBAR MENU
========================= */

const menuItems = [
  {
    name: "New order",
    path: "/",
    icon: "🛒",
  },
  {
    name: "Announcement group",
    path: "/announcements",
    icon: "◉",
  },
  {
    name: "Services",
    path: "/services",
    icon: "▣",
  },
  {
    name: "Orders",
    path: "/orders",
    icon: "👜",
  },
  {
    name: "Add funds",
    path: "/add-funds",
    icon: "pay",
  },
  {
    name: "API",
    path: "/api",
    icon: "⚒",
  },
  {
    name: "Affiliates",
    path: "/affiliates",
    icon: "♧",
  },
  {
    name: "Child panel",
    path: "/child-panel",
    icon: "♟",
  },
  {
    name: "Tickets",
    path: "/tickets",
    icon: "▰",
  },
  {
    name: "Mass order",
    path: "/mass-order",
    icon: "♧",
  },
  {
    name: "Updates",
    path: "/updates",
    icon: "🔧",
  },
];

